using Intranet.Entity;
using Intranet.Service;
namespace Intranet.Api.Tests;
public sealed class AnalisisRbPartialTests {
 private static AnalisisRbSave Request()=>new(){RequestId=Guid.NewGuid(),Source=new("J1825",217,1.404m,11.51m),UsedTime=1.07m,ServicePrice=1.30m,OtherExpenses=.03m,PartialSelection=new("99863","0","CS","COSTURA",11.51m,[new("948","PANTALON","001","369595","0","UNIR",.65m),new("948","PANTALON","002","146601","0","PESPUNTE",.42m)])};
 [Fact]public void PreservesSelectionAndPartialCalculations(){var request=Request();var result=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);Assert.Equal(1.07m,result.PartialSelection!.SelectedTime);Assert.Equal(2,result.PartialSelection.Operations.Count);Assert.Equal("CS",result.PartialSelection.Sector);Assert.Equal("0",result.PartialSelection.Variant);Assert.Equal("TIEMPO PARCIAL",result.Calculated.TimeLabel);Assert.Equal("COSTURA PARCIAL",result.Calculated.Observation);Assert.Equal(1.07m*1.404m/11.51m,result.Calculated.CommercialTotal);Assert.Equal(10.44m,result.Calculated.RemovedTime);var restored=System.Text.Json.JsonSerializer.Deserialize<AnalisisRbSnapshot>(System.Text.Json.JsonSerializer.Serialize(result));Assert.Equal(1.07m,restored!.PartialSelection!.SelectedTime);}
 [Fact]public void ExplicitPartialRemainsPartialEvenWhenTimeMatchesTotal(){var request=Request();request.UsedTime=11.51m;Assert.Equal("TIEMPO PARCIAL",AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today).Calculated.TimeLabel);}
 [Fact]public void OtherSectorUsesItsNameInObservation(){var request=Request();request.PartialSelection=request.PartialSelection! with{Sector="CO",SectorName="CORTE"};Assert.Equal("CORTE PARCIAL",AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today).Calculated.Observation);}
 [Fact]public void AllowsExistingManualTimeAdjustmentWithoutLosingOriginalSelection(){var request=Request();request.UsedTime=2;var result=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);Assert.Equal(2,result.UsedTime);Assert.Equal(1.07m,result.PartialSelection!.SelectedTime);}
 [Fact]public void SnapshotCopiesSelectionList(){var request=Request();var operations=request.PartialSelection!.Operations.ToList();request.PartialSelection=request.PartialSelection with{Operations=operations};var result=AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today);operations.Clear();Assert.Equal(2,result.PartialSelection!.Operations.Count);}
 [Theory][InlineData("empty")][InlineData("duplicate")][InlineData("negative")][InlineData("overflow")][InlineData("null")][InlineData("precision")]public void RejectsInvalidSelections(string mode){var request=Request();var selection=request.PartialSelection!;selection=mode switch{"empty"=>selection with{Operations=[]},"duplicate"=>selection with{Operations=[selection.Operations[0],selection.Operations[0]]},"negative"=>selection with{Operations=[selection.Operations[0] with{StandardTime=-1}]},"overflow"=>selection with{SectorTotalTime=.1m},"null"=>selection with{Operations=null!},_=>selection with{Operations=[selection.Operations[0] with{StandardTime=.1234567m}]}};request.PartialSelection=selection;Assert.Throws<ArgumentException>(()=>AnalisisRbHistoryService.BuildSnapshot(request,DateTime.Today));}
 [Fact]public void MvcCanValidateNestedPartialRecords(){var services=new Microsoft.Extensions.DependencyInjection.ServiceCollection();Microsoft.Extensions.DependencyInjection.LoggingServiceCollectionExtensions.AddLogging(services);Microsoft.Extensions.DependencyInjection.MvcServiceCollectionExtensions.AddControllers(services);using var provider=Microsoft.Extensions.DependencyInjection.ServiceCollectionContainerBuilderExtensions.BuildServiceProvider(services);var state=new Microsoft.AspNetCore.Mvc.ModelBinding.ModelStateDictionary();var context=new Microsoft.AspNetCore.Mvc.ActionContext(new Microsoft.AspNetCore.Http.DefaultHttpContext{RequestServices=provider},new Microsoft.AspNetCore.Routing.RouteData(),new Microsoft.AspNetCore.Mvc.Abstractions.ActionDescriptor(),state);var validator=(Microsoft.AspNetCore.Mvc.ModelBinding.Validation.IObjectModelValidator)provider.GetService(typeof(Microsoft.AspNetCore.Mvc.ModelBinding.Validation.IObjectModelValidator))!;validator.Validate(context,null,"",Request());Assert.True(state.IsValid);}
}
